namespace {
    /**
     * The application's clipboard, from QGuiApplication::clipboard().
     *
     * @not-serializable
     */
    class QClipboard extends QObject
    {
        private function __construct() {}

        public function setText(string $text, QClipboard\Mode $mode = QClipboard\Mode::CLIPBOARD): void {}

        public function text(QClipboard\Mode $mode = QClipboard\Mode::CLIPBOARD): string {}

        public function clear(QClipboard\Mode $mode = QClipboard\Mode::CLIPBOARD): void {}

        /** The clipboard's current data, owned by the clipboard: read it now, it can change on the next event. */
        public function mimeData(QClipboard\Mode $mode = QClipboard\Mode::CLIPBOARD): ?QMimeData {}
    }

    /**
     * @not-serializable
     */
    class QMimeData extends QObject
    {
        public function __construct() {}

        public function hasText(): bool {}

        /** @return string[] the MIME types the data holds */
        public function formats(): array {}
    }

    /**
     * @not-serializable
     */
    final class QDesktopServices
    {
        private function __construct() {}

        /** The URL in its handler (the browser for http and https). */
        public static function openUrl(QUrl $url): bool {}
    }

    final class QFontDatabase
    {
        private function __construct() {}

        /** Needs a QGuiApplication (QtException otherwise). */
        public static function systemFont(QFontDatabase\SystemFont $type): QFont {}
    }

    /**
     * A value in Qt; here a heap copy owned by the PHP object.
     *
     * @not-serializable
     */
    final class QFont
    {
        public function __construct(string $family, int $pointSize = -1, int $weight = -1, bool $italic = false) {}

        public function family(): string {}

        public function setFamily(string $family): void {}

        public function pointSizeF(): float {}

        /** @param float $pointSize greater than 0 */
        public function setPointSizeF(float $pointSize): void {}

        /** A weight between the named ones (a font match can produce one) comes back as the int. */
        public function weight(): QFont\Weight|int {}

        /** @param QFont\Weight|int $weight a named weight, or any point on the 1 to 1000 scale */
        public function setWeight(QFont\Weight|int $weight): void {}
    }

    /**
     * A value in Qt; here a heap copy owned by the PHP object. Sizes in points (fractional).
     * Needs a QGuiApplication (or QApplication) first.
     *
     * @not-serializable
     */
    final class QFontMetricsF
    {
        public function __construct(QFont $font) {}

        public function ascent(): float {}

        public function descent(): float {}

        public function lineSpacing(): float {}

        public function averageCharWidth(): float {}

        /** horizontalAdvance(const QString &, int len): the first $len characters; -1 = all. */
        public function horizontalAdvance(string $text, int $len = -1): float {}
    }

    /**
     * A value in Qt; here a heap copy owned by the PHP object: the font the window system matched.
     * Needs a QGuiApplication (or QApplication) first.
     *
     * @not-serializable
     */
    final class QFontInfo
    {
        public function __construct(QFont $font) {}

        public function fixedPitch(): bool {}
    }

    /**
     * Abstract in Qt: the base of what a QPainter paints on. QPixmap and QImage derive from it here;
     * QWidget, also one in Qt, derives from QObject only.
     *
     * @not-serializable
     */
    abstract class QPaintDevice
    {
    }

    /**
     * A value in Qt; here a heap copy owned by the PHP object.
     *
     * @not-serializable
     */
    final class QPixmap extends QPaintDevice
    {
        /** Needs a QGuiApplication (or QApplication) first. */
        public function __construct() {}

        /** Needs a QGuiApplication (or QApplication) first. */
        public static function fromImage(QImage $image, Qt\ImageConversionFlag|int $flags = Qt\ImageConversionFlag::AUTO_COLOR): QPixmap {}

        public function load(string $fileName, ?string $format = null, Qt\ImageConversionFlag|int $flags = Qt\ImageConversionFlag::AUTO_COLOR): bool {}

        public function isNull(): bool {}

        public function width(): int {}

        public function height(): int {}

        public function scaled(int $width, int $height, Qt\AspectRatioMode $aspectRatioMode = Qt\AspectRatioMode::IGNORE_ASPECT_RATIO, Qt\TransformationMode $transformMode = Qt\TransformationMode::FAST_TRANSFORMATION): QPixmap {}

        /** A null rect copies the whole pixmap. */
        public function copy(?QRect $rect = null): QPixmap {}

        public function devicePixelRatio(): float {}

        /** @param float $scaleFactor greater than 0 */
        public function setDevicePixelRatio(float $scaleFactor): void {}

        /** Qt's default colour is Qt::white; a QColor with alpha 0 makes the pixmap transparent. */
        public function fill(QColor $fillColor = new QColor(255, 255, 255)): void {}

        public function toImage(): QImage {}
    }

    /**
     * A value in Qt; here a heap copy owned by the PHP object. Made from a pixmap only.
     *
     * @not-serializable
     */
    final class QIcon
    {
        /** Needs a QGuiApplication (or QApplication) first, as the pixmap did. */
        public function __construct(QPixmap $pixmap) {}

        public function isNull(): bool {}

#if QT_VERSION >= QT_VERSION_CHECK(6, 7, 0)
        /** QIcon::fromTheme(name) or, with a QIcon\ThemeIcon, QIcon::fromTheme(icon) (Qt 6.7). Qt's null icon when the theme has none. */
        public static function fromTheme(string|QIcon\ThemeIcon $name): QIcon {}
#else
        /** Qt's null icon when the theme has none. */
        public static function fromTheme(string $name): QIcon {}
#endif
    }

    /**
     * A value in Qt; here a heap copy owned by the PHP object. Made from a Qt\CursorShape, after a
     * QGuiApplication (or QApplication): before one, Qt's constructor aborts the process
     * ("Must construct a QGuiApplication before a QPixmap").
     *
     * @not-serializable
     */
    final class QCursor
    {
        public function __construct(Qt\CursorShape $shape) {}

        public function shape(): Qt\CursorShape {}
    }

    /**
     * A value in Qt; here a heap copy owned by the PHP object.
     *
     * @not-serializable
     */
    final class QImage extends QPaintDevice
    {
        /**
         * QImage(data, width, height, bytesPerLine, format, cleanupFunction, cleanupInfo): Qt borrows
         * the buffer at the address $data (a QByteArray's or a framebuffer's pointer()), which must
         * outlive every image sharing it; copy() makes an image of its own. Once the last image
         * sharing the buffer goes, Qt calls $cleanupFunction($cleanupInfo), on the thread that
         * made the image. A null address or bad dimensions make Qt's null image.
         */
        public function __construct(int $data, int $width, int $height, int $bytesPerLine, QImage\Format $format, ?callable $cleanupFunction = null, mixed $cleanupInfo = null) {}

        public function isNull(): bool {}

        public function width(): int {}

        public function height(): int {}

        public function format(): QImage\Format {}

        /** $rect null is Qt's default QRect(): the whole image. */
        public function copy(?QRect $rect = null): QImage {}

        /** QRgb as an int: 0xAARRGGBB. Outside the image Qt warns and answers 12345. */
        public function pixel(int $x, int $y): int {}

        /** Outside the image Qt warns and answers an invalid colour. */
        public function pixelColor(int $x, int $y): QColor {}
    }

    /**
     * Heap item: PHP owns it until QTableWidget::setItem() hands it to a table.
     *
     * @not-serializable
     */
    final class QTableWidgetItem
    {
        /** @cvalue QTableWidgetItem::Type */
        public const int TYPE = UNKNOWN;
        /** @cvalue QTableWidgetItem::UserType */
        public const int USER_TYPE = UNKNOWN;

        public function __construct(string $text = "", int $type = QTableWidgetItem::TYPE) {}

        public function text(): string {}

        public function setText(string $text): void {}

        public function type(): int {}

        /** The item's row in its table; -1 when no table holds it. */
        public function row(): int {}
    }

    /**
     * Heap item: PHP owns it until QTreeWidget::addTopLevelItem() or addChild() hands it to a tree or a
     * parent item; its wrapper reports "deleted" once Qt deletes it (with its tree, its parent, or clear()).
     *
     * @not-serializable
     */
    final class QTreeWidgetItem
    {
        /** @cvalue QTreeWidgetItem::Type */
        public const int TYPE = UNKNOWN;
        /** @cvalue QTreeWidgetItem::UserType */
        public const int USER_TYPE = UNKNOWN;

        public function __construct(int $type = QTreeWidgetItem::TYPE) {}

        public function text(int $column): string {}

        public function setText(int $column, string $text): void {}

        public function foreground(int $column): QBrush {}

        public function setForeground(int $column, QBrush $brush): void {}

        /**
         * $role: a Qt\ItemDataRole value or a user role. The QVariant as PHP holds it: null when it holds
         * nothing; null, bool, int, float, string; Qt's value classes (QBrush, QColor, QFont, QPixmap,
         * QPoint, QSize, …) as their PHP classes; a type with no PHP class (QIcon) as null.
         */
        public function data(int $column, int $role): mixed {}

        /** $value as QVariant: null, bool, int, float, string, or one of Qt's value classes. */
        public function setData(int $column, int $role, mixed $value): void {}

        /**
         * The parent owns the child once Qt stored it; Qt ignores a child that already has a tree or a parent item.
         * Qt walks the new child's subtree with no cycle check: an item added under itself or under one of its
         * own descendants never returns.
         */
        public function addChild(QTreeWidgetItem $child): void {}

        public function childCount(): int {}

        public function child(int $index): ?QTreeWidgetItem {}

        /** Null for a top-level item, as for a loose one. */
        public function parent(): ?QTreeWidgetItem {}

        /** Read from the item's tree: false while no tree holds it. */
        public function isExpanded(): bool {}

        public function setExpanded(bool $expand): void {}

        public function childIndicatorPolicy(): QTreeWidgetItem\ChildIndicatorPolicy {}

        public function setChildIndicatorPolicy(QTreeWidgetItem\ChildIndicatorPolicy $policy): void {}
    }
}
